        properties: {
          input: {
            type: "string",
            description: "Raw tool input. For apply_patch, begin exactly with `*** Begin Patch` (no trailing `***`), then use its standard patch envelope.",
          },
        },
        required: ["input"],
      },
      freeform: true,
    };
